// Render course depth without adding another top-level navigation section.
function diagram(d){
 return `<figure class="architecture"><figcaption>Architecture · components and critical paths</figcaption>${d.architecture?componentDiagram(d):''}${d.flow.map((row,i)=>`<div class="diagram-lane"><span class="lane-number">${i+1}</span><div class="diagram-chain">${row.split(' → ').map((part,j)=>`${j?'<span class="diagram-arrow" aria-hidden="true">→</span>':''}<span class="diagram-node">${esc(part)}</span>`).join('')}</div></div>`).join('')}<p class="small">Arrows show the sequence along each path; adjacent lanes may share components. Durable ownership and acknowledgment boundaries are defined in the walkthrough.</p></figure>`;
}
function componentDiagram(d){const a=d.architecture;const positions=[[10,20],[225,20],[440,20],[10,190],[225,190],[440,190]];const edges=a.edges.map(([from,to,label],i)=>{const [x,y]=positions[from],[tx,ty]=positions[to];const same=y===ty;const sx=same?x+175:x+87.5,sy=same?y+30:y+(ty>y?60:0),ex=same?tx:tx+87.5,ey=same?ty+30:ty+(ty>y?0:60);const mid=(sy+ey)/2+(i%3-1)*14;return `<path d="M ${sx} ${sy} ${same?'L '+ex+' '+ey:'L '+sx+' '+mid+' L '+ex+' '+mid+' L '+ex+' '+ey}" marker-end="url(#arrow-${d.id})"/><text class="edge-label" x="${same?(sx+ex)/2:(sx+ex)/2}" y="${same?y-8:mid-5}" text-anchor="middle">${esc(label)}</text>`;}).join('');return `<div class="architecture-scroll"><svg class="architecture-svg" viewBox="0 0 630 275" role="img" aria-label="${esc(d.title)} component diagram"><title>${esc(d.title)} component diagram</title><desc>${esc(a.edges.map(([f,t,l])=>a.nodes[f]+' to '+a.nodes[t]+': '+l).join('. '))}</desc><defs><marker id="arrow-${d.id}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs>${edges}${a.nodes.map((label,i)=>`<rect x="${positions[i][0]}" y="${positions[i][1]}" width="175" height="60" rx="5"/><text class="node-label" x="${positions[i][0]+87.5}" y="${positions[i][1]+35}" text-anchor="middle">${esc(label)}</text>`).join('')}</svg></div>`;}
function designHints(d){const w=d.walkthrough;return `<section class="hint-section"><h2>Get unstuck without seeing the solution</h2>${w.hints.map((h,i)=>`<details><summary>Hint ${i+1}${i===0?' · identify the constraint':' · trace the difficult case'}</summary><p>${esc(h)}</p></details>`).join('')}</section>`;}
function designDepth(d){const w=d.walkthrough;return `<section id="deep-dive"><h2>7. Work the numbers further</h2><p>${esc(w.calculation)}</p><h2>8. Compare alternatives</h2><div class="alternatives">${w.alternatives.map((a,i)=>`<div><h3>Option ${i+1}</h3><p>${esc(a)}</p></div>`).join('')}</div><h2>9. Walk through a failure</h2><ol class="timeline">${w.timeline.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><h2>10. Evolve the system safely</h2><p>${esc(w.migration)}</p></section>`;}
function followupAnswers(d){return d.followup.map((question,i)=>`<details><summary>${esc(question)}</summary><p>${esc(d.walkthrough.answers[i])}</p></details>`).join('');}
function comparison(d){return `<details><summary>Compare weak and strong interview reasoning</summary><div class="reasoning-example"><h3>Weak answer</h3><p>${esc(d.walkthrough.weak)}</p><h3>Stronger answer</h3><p>${esc(d.walkthrough.strong)}</p><p class="small">Explain the invariant, mechanism, failure boundary and tradeoff in your own words. This comparison is feedback on reasoning, not a script to memorize.</p></div></details>`;}
function labCards(){return `<section id="labs"><div class="section-heading"><h2>Run it. Break it. Explain it.</h2><span>4 executable labs · Node.js 22.13+ · no dependencies</span></div><p class="small">Run locally from the repository, or download the self-contained runner and use <code>node labs.cjs all</code>. SQLite labs use disposable temporary databases. Each lab includes assertions and prints its measurements; the website does not execute backend processes.</p><div class="actions"><a class="button secondary" href="labs.cjs" download>Download lab runner ↓</a><a class="button secondary" href="https://github.com/builtbyankit/system-design-path/tree/main/labs" target="_blank" rel="noopener noreferrer">Browse lab source ↗</a></div>${window.COURSE.labs.map(l=>`<details><summary>${esc(l.title)}</summary><p><strong>Hypothesis.</strong> ${esc(l.hypothesis)}</p><pre><code>${esc(l.command)}\n# Downloaded runner alternative:\nnode labs.cjs ${l.id}</code></pre><ol>${l.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p><strong>Expected evidence.</strong> ${esc(l.expected)}</p><p><strong>Extend it.</strong> ${esc(l.extension)}</p><p class="small"><strong>What this does not prove.</strong> ${esc(l.limits)}</p><a class="button secondary" href="#lesson/${l.lesson}">Study the underlying concept →</a></details>`).join('')}</section>`;}
function relatedLabs(id){const lab=window.COURSE.labs.filter(l=>l.lesson===id||id==='lab-method');return lab.length?`<div class="callout"><strong>Test this idea with a runnable lab</strong>${lab.map(l=>`<p>${esc(l.title)}<br><code>${esc(l.command)}</code></p>`).join('')}<a href="#learn" class="button secondary">Lab instructions are on Learn →</a> <a href="labs.cjs" download class="button secondary">Download runner ↓</a></div>`:'';}
